import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
// Importing the Firebase auth instance we set up in Session 10
import { auth } from '../Session 10/firebase';

const Navbar = () => {
  const [user, setUser] = useState(null);

  useEffect(() => {
    // onAuthStateChanged listens to login/logout events
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });

    // Cleanup subscription when the component unmounts
    return () => unsubscribe();
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      // The onAuthStateChanged listener will automatically update the 'user' state to null
    } catch (error) {
      console.error('Error signing out:', error);
    }
  };

  return (
    <nav style={styles.navbar}>
      <div style={styles.logo}>Session 11 App</div>
      <div style={styles.userInfo}>
        {/* Display welcome message based on auth state */}
        <span style={{ marginRight: user ? '15px' : '0' }}>
          {user ? `Welcome, ${user.email}` : 'Welcome, Guest'}
        </span>

        {/* Only show the Logout button if the user is currently logged in */}
        {user && (
          <button onClick={handleLogout} style={styles.logoutBtn}>
            Logout
          </button>
        )}
      </div>
    </nav>
  );
};

const styles = {
  navbar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '15px 30px',
    backgroundColor: '#004d40',
    color: 'white',
    fontFamily: 'Arial, sans-serif',
    boxShadow: '0 2px 5px rgba(0,0,0,0.2)',
    marginBottom: '20px'
  },
  logo: {
    fontSize: '20px',
    fontWeight: 'bold'
  },
  userInfo: {
    fontSize: '16px',
    display: 'flex',
    alignItems: 'center'
  },
  logoutBtn: {
    padding: '6px 12px',
    backgroundColor: '#ff5252',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontWeight: 'bold'
  }
};

export default Navbar;
